[JsonConverter(typeof(AuthenticationRequestConverter))]
public interface AuthenticationRequest
{
}

/// <summary>Reads <see cref="AuthenticationRequest"/> by dispatching on its 'grant_type' tag.</summary>
public sealed class AuthenticationRequestConverter : JsonConverter<AuthenticationRequest>
{
    public override AuthenticationRequest Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var element = document.RootElement;
        var tag = element.TryGetProperty("grant_type", out var tagElement) && tagElement.ValueKind == JsonValueKind.String
            ? tagElement.GetString()
            : null;

        return tag switch
        {
            "password" => element.Deserialize<PasswordAuthenticationRequest>(options)!,
            "client_credentials" => element.Deserialize<ClientCredentialsAuthenticationRequest>(options)!,
            "refresh_token" => element.Deserialize<RefreshTokenAuthenticationRequest>(options)!,
            "link" => element.Deserialize<LinkAuthenticationRequest>(options)!,
            "code" => element.Deserialize<CodeAuthenticationRequest>(options)!,
            "fido" => element.Deserialize<FidoAuthenticationRequest>(options)!,
            "authenticator" => element.Deserialize<AuthenticatorAuthenticationRequest>(options)!,
            "oidc" => element.Deserialize<OidcAuthenticationRequest>(options)!,
            _ => throw new JsonException($"Unknown AuthenticationRequest grant_type: {tag}"),
        };
    }

    public override void Write(Utf8JsonWriter writer, AuthenticationRequest value, JsonSerializerOptions options)
    {
        switch (value)
        {
            case PasswordAuthenticationRequest member:
                JsonSerializer.Serialize(writer, member, options);
                break;
            case ClientCredentialsAuthenticationRequest member:
                JsonSerializer.Serialize(writer, member, options);
                break;
            case RefreshTokenAuthenticationRequest member:
                JsonSerializer.Serialize(writer, member, options);
                break;
            case LinkAuthenticationRequest member:
                JsonSerializer.Serialize(writer, member, options);
                break;
            case CodeAuthenticationRequest member:
                JsonSerializer.Serialize(writer, member, options);
                break;
            case FidoAuthenticationRequest member:
                JsonSerializer.Serialize(writer, member, options);
                break;
            case AuthenticatorAuthenticationRequest member:
                JsonSerializer.Serialize(writer, member, options);
                break;
            case OidcAuthenticationRequest member:
                JsonSerializer.Serialize(writer, member, options);
                break;
            default:
                throw new JsonException($"Unknown AuthenticationRequest member {value.GetType().Name}.");
        }
    }
}

